"""Reproduce Stage 2 using the already independently completed Stage 1 output.
Does not reclassify generated collision data as original clean source input.
"""
from pathlib import Path
import hashlib,json,subprocess,shutil,sys
HERE=Path(__file__).resolve().parent;BASE=HERE.parent;CAT=BASE.parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
receipt=CAT/'qa/batch16/independent_rebuild_auditorium_use_r07.json';stage1=json.loads(receipt.read_text());assert stage1['passed']and stage1['fresh_input_only_stage']and stage1['source_only_build_duplicated_by_reviewer']
rebuilt_base=CAT/stage1['stage']/'assets/auditorium_use/collision_proposals.json';assert sha(rebuilt_base)==sha(BASE/'collision_proposals.json')
stage=HERE/'two_stage_rebuild';assert not stage.exists(),'Preserve earlier reproduction stages; never silently replace'
stage.mkdir();shutil.copy2(HERE/'build_body_subset.py',stage/'build_body_subset.py');shutil.copy2(rebuilt_base,stage/'stage_one_generated_collision_proposals.json')
initial=[{'file':p.name,'sha256':sha(p),'role':'original new selector source'if p.suffix=='.py'else'explicitly generated Stage 1 collision data'}for p in sorted(stage.iterdir())]
cmd=[sys.executable,str(stage/'build_body_subset.py'),'--base-collision',str(stage/'stage_one_generated_collision_proposals.json'),'--output',str(stage/'body_collision_subset.json')];run=subprocess.run(cmd,text=True,capture_output=True);(HERE/'two_stage_rebuild.log').write_text(run.stdout+run.stderr);assert run.returncode==0,run.stderr
same=sha(stage/'body_collision_subset.json')==sha(HERE/'body_collision_subset.json')
sources=[BASE/'source/build_auditorium_use.py',BASE/'source/draw_markings.py',BASE/'source/AST-CUL-003.blend',BASE/'source/AST-CUL-004.blend',BASE/'collision_proposals.json',BASE/'marker_api.json',BASE/'AST-CUL-003.manifest.json',BASE/'AST-CUL-004.manifest.json',BASE/'qa/source_only_rebuild.json',BASE/'qa/auditorium_use_source_only_inputs.zip',receipt]
out={'schema':'optional_body_two_stage_reproduction_v1','stage_one':{'performed_again_in_this_addendum':False,'existing_independent_receipt':str(receipt.relative_to(CAT)),'receipt_sha256':sha(receipt),'original_clean_rebuild_passed':stage1['passed'],'stage_one_generated_base':str(rebuilt_base.relative_to(CAT)),'generated_base_sha256':sha(rebuilt_base),'production_base_sha256':sha(BASE/'collision_proposals.json'),'bases_byte_identical':sha(rebuilt_base)==sha(BASE/'collision_proposals.json'),'description':'Reuse the previously completed independent original source-only rebuild and its exact generated detailed collision JSON; do not claim this generated JSON is an original clean source input.'},'stage_two':{'initial_inputs':initial,'command':cmd,'exit_code':run.returncode,'generator_sha256':sha(HERE/'build_body_subset.py'),'expected_body_subset_sha256':sha(HERE/'body_collision_subset.json'),'reproduced_body_subset_sha256':sha(stage/'body_collision_subset.json'),'byte_identical':same,'prior_body_subset_used_as_input':False,'no_blender_or_render_run':True},'frozen_source_and_base_bindings':[{'path_from_catalogue_root':str(p.relative_to(CAT)),'sha256':sha(p)}for p in sources],'all_passed':same and run.returncode==0};(HERE/'two_stage_reproduction.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'all_passed':out['all_passed'],'stage_one_generated_dependency_explicit':True,'stage_two_byte_identical':same},indent=2))
